//! Real OUTPUT text replacement, identity and bounded publication.
use super::*;
fn fixture()->(Document,Forms,Page){fixture_content("<span id=old>before</span>tail")}
fn fixture_content(content:&str)->(Document,Forms,Page){let mut d=crate::html::parse(&format!("<html><body><form id=owner><label id=label for=output>Result</label><output id=output for=seed name=result>{content}</output><input id=field value=seed></form><div id=mount></div></body></html>"));d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-text.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn output_text_replacement_exact_text_identity_records_and_ranges(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),old=output.firstChild,tail=output.lastChild,list=output.childNodes,labels=output.labels,tokens=output.htmlFor,owner=output.form,range=new Range(),watch=new MutationObserver(function(){});range.setStart(old.firstChild,1);range.setEnd(tail,2);watch.observe(output,{childList:true});output.textContent='A\ud800z<&';var fresh=output.firstChild,records=watch.takeRecords();if(output.textContent!=='A\ud800z<&'||fresh.data!==output.textContent||list.length!==1||list[0]!==fresh||fresh===tail||fresh===old.firstChild||old.parentNode!==null||tail.parentNode!==null||old.textContent!=='before'||tail.data!=='tail')throw 'actual exact replacement';if(records.length!==1||records[0].target!==output||records[0].removedNodes.length!==2||records[0].removedNodes[0]!==old||records[0].removedNodes[1]!==tail||records[0].addedNodes.length!==1||records[0].addedNodes[0]!==fresh||records[0].previousSibling!==null||records[0].nextSibling!==null)throw 'replacement record identities';if(range.startContainer!==output||range.endContainer!==output||range.startOffset||range.endOffset||!range.collapsed||output.labels!==labels||labels[0].control!==output||output.htmlFor!==tokens||tokens.value!=='seed'||output.form!==owner||output.name!=='result')throw 'ranges and independent output authority';"#);}
#[test]
fn output_text_replacement_empty_and_detached_native_output(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),old=output.firstChild;output.textContent=null;if(output.textContent!==''||output.childNodes.length||old.parentNode!==null)throw 'empty replacement';output.textContent='fresh';var fresh=output.firstChild;output.textContent='fresh';if(output.firstChild===fresh||fresh.parentNode!==null||fresh.data!=='fresh')throw 'new text even equal contents';var made=document.createElement('output');made.textContent='A\udfffz';if(made.isConnected||made.firstChild.data!=='A\udfffz'||made.textContent!=='A\udfffz')throw 'detached real output';document.getElementById('mount').appendChild(made);made.textContent='connected';if(made.firstChild.data!=='connected'||!made.isConnected)throw 'connected created output';"#);}
#[test]
fn output_text_replacement_parent_can_retire_output_without_changing_saved_associations(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),mount=document.getElementById('mount'),labels=output.labels;mount.appendChild(output);mount.textContent='replacement';if(output.parentNode!==null||output.isConnected||output.textContent!=='beforetail'||output.form!==null||output.labels!==labels||labels.length||mount.firstChild.data!=='replacement')throw 'ordinary parent retires passive output';"#);}

#[test]
fn output_text_replacement_conversion_reentry_abrupt_and_native_descriptor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),set=Object.getOwnPropertyDescriptor(Node.prototype,'textContent').set,get=Object.getOwnPropertyDescriptor(Node.prototype,'textContent').get,calls=0,during,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});set.call(output,{toString:function(){calls++;output.textContent='during';during=output.firstChild;return 'A\ud800z';}});var after=output.firstChild,records=watch.takeRecords();if(calls!==1||records.length!==2||records[0].addedNodes[0]!==during||records[1].removedNodes[0]!==during||records[1].addedNodes[0]!==after||after.data!=='A\ud800z')throw 'current children after conversion';var marker={},caught;try{output.textContent={toString:function(){output.textContent='effect';throw marker;}};}catch(e){caught=e;}if(caught!==marker||output.textContent!=='effect'||watch.takeRecords().length!==1)throw 'completed conversion effects';caught=false;try{output.textContent=Symbol('bad');}catch(e){caught=e instanceof TypeError;}if(!caught||output.textContent!=='effect'||watch.takeRecords().length)throw 'symbol before publication';Object.defineProperty(output,'textContent',{value:'author',writable:true,configurable:true});set.call(output,'native');if(output.textContent!=='author'||get.call(output)!=='native'||output.firstChild.data!=='native')throw 'saved native descriptor ignores shadow';delete output.textContent;if(output.textContent!=='native')throw 'restored inherited native text';"#);}
#[test]
fn output_text_replacement_protected_descendants_keep_native_state_and_recover(){for content in ["<input id=protected value=seed>","<button id=protected>caption</button>","<textarea id=protected>seed</textarea>","<img id=protected src=missing>","<script id=protected>saved</script>","<style id=protected>saved{color:red}</style>","<iframe id=protected></iframe>","<svg><output id=protected>foreign</output></svg>"]{let(mut d,mut f,mut p)=fixture_content(content);run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),old=output.firstChild,range=new Range(),watch=new MutationObserver(function(){});range.selectNode(old);watch.observe(output,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let ranges=format!("{:?}",p.state.ranges);let controls=f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.caption.clone())).collect::<Vec<_>>();p.begin_job();let e=p.runtime.execute("output.textContent='blocked';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("cannot remove controls"),"{content}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(format!("{:?}",p.state.ranges),ranges);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.caption.clone())).collect::<Vec<_>>(),controls);p.begin_job();run(&mut d,&mut f,&mut p,"if(output.firstChild!==old||old.parentNode!==output||watch.takeRecords().length||range.startContainer!==output||range.startOffset!==0||range.endOffset!==1)throw 'protected native publication';var fresh=document.createElement('output');fresh.textContent='recovered';if(fresh.firstChild.data!=='recovered')throw 'fresh output recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());}}
#[test]
fn output_text_replacement_work_copy_storage_deadline_and_string_limits_are_atomic(){for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),old=output.firstChild,watch=new MutationObserver(function(){}),range=new Range();range.selectNodeContents(old);watch.observe(output,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let ranges=format!("{:?}",p.state.ranges);let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.limits.host.string_bytes=1};let e=p.runtime.execute("output.textContent='long A\\ud800z replacement';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(format!("{:?}",p.state.ranges),ranges);p.state.retained_limit=limit;p.state.execution_deadline=None;p.state.limits.host.string_bytes=strings;p.begin_job();run(&mut d,&mut f,&mut p,"if(output.firstChild!==old||watch.takeRecords().length)throw 'atomic failed replacement';output.textContent='fresh';if(output.firstChild.data!=='fresh'||watch.takeRecords().length!==1)throw 'fresh replacement recovery';");}}
#[test]
fn output_text_replacement_scratch_admits_old_and_new_backing_with_input_and_other_vectors(){let(mut d,mut f,mut p)=fixture();let original=p.state.retained_limit;let mut values=Vec::with_capacity(4);values.extend([1,2,3,4]);let old=values.capacity()*size_of::<usize>();let other=37;let required=(values.len()+1)*size_of::<usize>();p.begin_job();p.state.retained_limit=p.state.retained+other+old+required-1;let before=values.clone();let cap=values.capacity();assert!(script_text_replacement::push(&mut p.state,&mut values,5,other).unwrap_err().contains("storage allowance"));assert_eq!(values,before);assert_eq!(values.capacity(),cap);p.state.retained_limit=original;p.begin_job();script_text_replacement::push(&mut p.state,&mut values,5,other).unwrap();assert_eq!(values,[1,2,3,4,5]);let content=(0..24).map(|_|"<span>leaf</span>").collect::<String>();let(mut d2,mut f2,mut p2)=fixture_content(&content);p2.state.rebuild(&d2).unwrap();let node=(0..d2.nodes.len()).find(|&n|d2.attr(n,"id")==Some("output")).unwrap();let text=DomString::from("replacement");let limit=p2.state.retained_limit;p2.state.retained_limit=p2.state.retained+text.capacity()+256;let snapshot=format!("{:?}",d2.nodes);let state=(p2.state.retained,p2.state.dom_commits,p2.state.detached_nodes.clone());p2.begin_job();let e=Bridge{doc:&mut d2,forms:&mut f2,state:&mut p2.state}.set_text_content(node,text).unwrap_err();assert!(e.contains("traversal storage"),"{e}");assert_eq!(format!("{:?}",d2.nodes),snapshot);assert_eq!((p2.state.retained,p2.state.dom_commits,p2.state.detached_nodes.clone()),state);p2.state.retained_limit=limit;p2.begin_job();run(&mut d2,&mut f2,&mut p2,"document.getElementById('output').textContent='recovered';");run(&mut d,&mut f,&mut p,"if(document.getElementById('output').textContent!=='beforetail')throw 'scratch changed DOM';");}
#[test]
fn output_text_replacement_node_limit_refuses_text_but_allows_empty_without_new_slot(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),old=output.firstChild,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);let limit=p.state.node_limit;let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();assert!(p.runtime.execute("output.textContent='blocked';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err().contains("node limit"));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length)throw 'failed node admission records';output.textContent=null;if(output.childNodes.length||old.parentNode!==null||watch.takeRecords().length!==1)throw 'empty needs no slot';");assert_eq!(d.nodes.len(),slots);p.state.node_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"output.textContent='fresh';if(output.firstChild.data!=='fresh')throw 'new-slot recovery';");}
#[test]
fn output_text_replacement_inert_clone_adoption_and_whole_import_boundary(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('output');output.textContent='A\ud800z';var old=output.firstChild,copy=output.cloneNode(true),target=document.implementation.createHTMLDocument('target');target.adoptNode(copy);copy.textContent='B\udfffz';if(output.textContent!=='A\ud800z'||old!==output.firstChild||copy.textContent!=='B\udfffz'||copy.ownerDocument!==target||copy.firstChild.ownerDocument!==target)throw 'independent inert clones and adoption';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.begin_job();assert!(p.runtime.execute("document.importNode(copy,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err().contains("Import supports ordinary HTML containers"));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.begin_job();run(&mut d,&mut f,&mut p,"copy.textContent='fresh';if(copy.textContent!=='fresh'||output.firstChild!==old)throw 'inert refusal recovery';");}
#[test]
fn output_text_replacement_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.Node.prototype,'textContent'),calls=0;descriptor.set.call(output,'saved');if(descriptor.get.call(output)!=='saved')throw 'saved child text';");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-output-text.test/",&crate::navigation::Location::home()).unwrap());for expression in ["descriptor.set.call(output,{toString:function(){calls++;return 'bad';}});","descriptor.get.call(output);"]{p.begin_job();let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://output-text.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||output.textContent!=='saved')throw 'origin before conversion';descriptor.set.call(output,'fresh');if(output.textContent!=='fresh')throw 'fresh captured text recovery';");}
